var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Original behavior: y = d * 365.25 → 1 year = 365.25 days
    // Patched behavior: y = d / 365.25 → 1 year = 1/365.25 days (~24.5 minutes)
    // This is clearly wrong: a year should be longer than a day.
    // Test: parse '1y' should return a large number in original, tiny in patched.
    // We expect the original to return ~31,557,600,000 ms (365.25 * 24 * 60 * 60 * 1000)
    // The patched version returns ~24,500 ms, which is wrong.

    const originalYearMs = 365.25 * 24 * 60 * 60 * 1000; // ~31.5576 million seconds
    const parsed = ms('1y');

    // In original, '1y' should be ~31.5576 million seconds
    // In patched, it's ~24.5 seconds → clearly wrong
    // So the patched version is broken.

    // We assert that the patched version does NOT return the correct value
    // The original should pass, the patched should fail.
    assert.notEqual(parsed, 24500, 'Year should not be 24.5 seconds');
    assert(parsed > 30000000, 'Year should be over 30 million ms');
  });
});

